#include <stddef.h>
#include <stdio.h>

struct A { char c; short s; };          /* c@0, pad 1, s@2        -> 4  */
struct B { short s; char c; int i; };   /* s@0, c@2, pad 1, i@4   -> 8  */
struct C { char c; double d; int i; };  /* c@0, pad 7, d@8, i@16,
                                           tail pad 4             -> 24 */
struct D { double d; int i; char c; };  /* d@0, i@8, c@12,
                                           tail pad 3             -> 16 */

int main(void) {
    printf("%zu %zu %zu %zu\n", sizeof(struct A), sizeof(struct B),
           sizeof(struct C), sizeof(struct D));       /* 4 8 24 16 */
    printf("%zu\n", offsetof(struct C, i));           /* 16 */
    return 0;
}

